#!/bin/bash
set -e

# ==============================================================
# Kavian CopyTrade v3.9.9 Pro - Complete Standalone All-in-One Installer
# Path: /opt/kaviancopytrade | Port: 8900
#
# Full Production Feature Set (Fresh Server or In-Place Upgrade):
#   - Everything in v2.7 Pro PLUS:
#   - Multi-Select & Bulk Close Open Positions (Both Admin & All Users):
#       * Checkbox column + Select All + 1-Click "Select Profitable" button
#         + "Close Selected (N)" parallel market-exit engine across:
#           1) User Trader Portal (/dashboard -> Active Open Positions)
#           2) Admin Exchange Tab (/admin -> My Personal Exchange Positions)
#           3) Admin User Report Page (/admin -> Users -> Report)
#       * Live floating PnL column added to Admin Personal Positions
#       * Selection state preserved cleanly across live auto-refresh cycles
#       * Thread-safe Paper balance accounting & strict user ownership guard
#
# Usage:
#   1) Fresh Ubuntu/Debian server install OR zero-data-loss upgrade:
#      bash install_kaviancopytrade_v3_9_9.sh
#   2) Fresh install + immediate Domain & Free Let's Encrypt HTTPS SSL:
#      bash install_kaviancopytrade_v3_9_9.sh copy.yourdomain.com admin@yourdomain.com
# ==============================================================

APP_DIR="/opt/kaviancopytrade"
PORT="8900"
DOMAIN_ARG="${1:-}"
EMAIL_ARG="${2:-}"

echo "========================================================"
echo "  Kavian CopyTrade v3.9.9 Pro - Unified Installer"
echo "  Custom Paper ($100-$10K) | Auth Fix | Bulk Close | Chat"
echo "========================================================"

echo "=== [1/7] Preparing $APP_DIR (preserving existing DB/config/SSL) ==="
systemctl stop kaviancopytrade.service 2>/dev/null || true
mkdir -p "$APP_DIR" "$APP_DIR/backups" "$APP_DIR/static"
cd "$APP_DIR"

SCRIPT_SRC="$(readlink -f "$0" 2>/dev/null || echo "$0")"
if [ -f "$SCRIPT_SRC" ] && [ "$SCRIPT_SRC" != "$APP_DIR/install_kaviancopytrade_v3_9_9.sh" ]; then
    cp -f "$SCRIPT_SRC" "$APP_DIR/install_kaviancopytrade_v3_9_9.sh" 2>/dev/null || true
    chmod +x "$APP_DIR/install_kaviancopytrade_v3_9_9.sh" 2>/dev/null || true
fi

echo "=== [2/7] Installing system packages (Python, PostgreSQL, Nginx, Certbot) ==="
export DEBIAN_FRONTEND=noninteractive
apt-get update -y
apt-get install -y python3 python3-venv python3-pip curl openssl postgresql postgresql-contrib nginx certbot python3-certbot-nginx

systemctl enable postgresql
systemctl start postgresql

echo "=== [3/7] Configuring PostgreSQL database & .env Vault ==="
ENV_FILE="$APP_DIR/.env"
if [ ! -f "$ENV_FILE" ]; then
    DB_PASS=$(openssl rand -hex 20)
    SECRET_KEY=$(openssl rand -hex 32)
    MASTER_ENC_KEY=$(python3 -c "import os, base64; print(base64.urlsafe_b64encode(os.urandom(32)).decode('ascii'))")
    INIT_ADMIN_PASS="admin12345"

    sudo -u postgres psql -tc "SELECT 1 FROM pg_roles WHERE rolname='kaviancopytrade'" | grep -q 1 ||         sudo -u postgres psql -c "CREATE USER kaviancopytrade WITH PASSWORD '$DB_PASS';"
    sudo -u postgres psql -c "ALTER USER kaviancopytrade WITH PASSWORD '$DB_PASS';" >/dev/null
    sudo -u postgres psql -tc "SELECT 1 FROM pg_database WHERE datname='kaviancopytrade'" | grep -q 1 ||         sudo -u postgres psql -c "CREATE DATABASE kaviancopytrade OWNER kaviancopytrade;"
    sudo -u postgres psql -c "GRANT ALL PRIVILEGES ON DATABASE kaviancopytrade TO kaviancopytrade;" >/dev/null
    sudo -u postgres psql -d kaviancopytrade -c "GRANT ALL ON SCHEMA public TO kaviancopytrade;" >/dev/null 2>&1 || true

    cat << EOF_ENV > "$ENV_FILE"
DATABASE_URL=postgresql://kaviancopytrade:$DB_PASS@127.0.0.1:5432/kaviancopytrade
SECRET_KEY=$SECRET_KEY
MASTER_ENC_KEY=$MASTER_ENC_KEY
INIT_ADMIN_USER=admin
INIT_ADMIN_EMAIL=admin@kaviancopytrade.local
INIT_ADMIN_PASS=$INIT_ADMIN_PASS
PORT=$PORT
EOF_ENV
    chmod 600 "$ENV_FILE"
    echo "Created PostgreSQL database 'kaviancopytrade' & secured .env (chmod 600)."
else
    echo "Existing $ENV_FILE preserved (PostgreSQL credentials & AES master key intact)."
fi

echo "=== [4/7] Extracting Kavian CopyTrade v3.9.9 Pro core modules ==="
